public sealed class ExecutionsController(ExecutionService service,DefectAutoCreateService defectAuto):ControllerBase
{
 [HttpGet("test-cycles/{cycleId:guid}/execution")]public async Task<ActionResult<ExecutionWorkspaceDto>>Workspace(Guid cycleId,CancellationToken ct){try{return Ok(await service.WorkspaceAsync(cycleId,ct));}catch(EntityNotFoundException){return NotFound();}}[HttpGet("test-cycles/{cycleId:guid}/cases/{cycleCaseId:guid}")]public async Task<ActionResult<CycleCaseDetailDto>>CaseDetail(Guid cycleId,Guid cycleCaseId,CancellationToken ct){try{return Ok(await service.CaseDetailAsync(cycleId,cycleCaseId,ct));}catch(EntityNotFoundException){return NotFound();}}[HttpPost("test-cycle-cases/{cycleCaseId:guid}/executions")]public async Task<ActionResult<ExecutionHistoryDto>>Create(Guid cycleCaseId,CreateExecutionRequest r,CancellationToken ct){try{var result=await service.CreateAsync(cycleCaseId,r,UserId(),ct);string? createdDefectCode=null;string? existingDefectCode=null;string? defectAutoCreateError=null;if(result.Status=="Fail"){var defectResult=await defectAuto.CreateFromFailAsync(cycleCaseId,r,UserId(),ct);createdDefectCode=defectResult.CreatedDefectCode;existingDefectCode=defectResult.ExistingDefectCode;defectAutoCreateError=defectResult.Error;}return Ok(new ExecutionHistoryDto(result.TestExecutionId,result.ExecutionNo,result.Status,result.ActualResult,result.Comment,result.TesterName,result.CompletedAt,createdDefectCode,existingDefectCode,defectAutoCreateError));}catch(EntityNotFoundException){return NotFound();}catch(ArgumentException ex){return BadRequest(new ProblemDetails{Title="ผลการทดสอบไม่ถูกต้อง",Detail=ex.Message,Status=400});}}[HttpDelete("executions/{executionId:guid}")]public async Task<IActionResult>Delete(Guid executionId,CancellationToken ct){try{await service.DeleteAsync(executionId,UserId(),ct);return NoContent();}catch(EntityNotFoundException){return NotFound();}}private Guid?UserId()=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var id)?id:null;
